  /* 修正 No.38 (2026-04-25): localStorage から services の connected / zoomPmi を復元 */
  private restoreServicesFromStorage(): void {
    try {
      const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(ServicePageComponent.STORAGE_KEY) : null;
      if (!raw) return;
      const data = JSON.parse(raw);
      if (!data || typeof data !== 'object') return;
      if (data.connected && typeof data.connected === 'object') {
        this.services.forEach(s => {
          if (typeof data.connected[s.name] === 'boolean') {
            s.connected = data.connected[s.name];
          }
        });
      }
      if (typeof data.zoomPmi === 'string' && data.zoomPmi) {
        this.zoomPmi = data.zoomPmi;
        const zoomService = this.services.find(s => s.name === 'Zoom');
        if (zoomService) zoomService.connectedInfo = `PMI: ${this.zoomPmi}`;
      }
    } catch (err) {
      console.warn('[ServicePage] failed to restore services:', err);
    }
  }

  /* 修正 No.38 (2026-04-25): 連携状態を localStorage に永続化 */
  private persistServices(): void {
    try {
      const connected: Record<string, boolean> = {};
      this.services.forEach(s => { connected[s.name] = !!s.connected; });
      const data = { connected, zoomPmi: this.zoomPmi };
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(ServicePageComponent.STORAGE_KEY, JSON.stringify(data));
      }
    } catch (err) {
      console.warn('[ServicePage] failed to persist services:', err);
    }
  }

  toggleService(index: number): void {
    this.services[index].connected = !this.services[index].connected;
    const service = this.services[index];
    if (service.connected) {
      this.notification.success(`${service.name}と連携しました`);
    } else {
      this.notification.warn(`${service.name}の連携を解除しました`);
    }
    /* 修正 No.38 (2026-04-25): 変更の度に永続化 */
    this.persistServices();
  }

  openZoomDialog(): void {
    this.showZoomDialog = true;
  }

  closeZoomDialog(): void {
    this.showZoomDialog = false;
  }

  saveZoomSettings(): void {
    // PMIバリデーション
    if (!this.zoomPmi || this.zoomPmi.trim() === '') {
      this.notification.error('PMI IDを入力してください');
      return;
    }
    // PMIを更新
    const zoomService = this.services.find(s => s.name === 'Zoom');
    if (zoomService) {
      zoomService.connectedInfo = `PMI: ${this.zoomPmi}`;
    }
    this.showZoomDialog = false;
    this.notification.success('Zoom設定を保存しました');
    /* 修正 No.38 (2026-04-25): Zoom PMI 変更時も永続化 */
    this.persistServices();
  }

  onConfigureClick(service: ServiceIntegration): void {
    if (service.name === 'Zoom') {
      this.openZoomDialog();
    }
  }
